{
  "nl": {
    "issue": [
      {
        "text": "借款合同的界定，以及借款人到期返还借款并支付利息的义务",
        "rules": ["c667-1", "c667-oblig"]
      },
      {
        "text": "借款合同是否应当采用书面形式，以及合同一般包括的内容",
        "rules": ["c668-1"]
      },
      {
        "text": "利息预先在本金中扣除的，如何处理",
        "rules": ["c670-for", "c670-1"]
      },
      {
        "text": "利息支付期限有约定、没有约定或者约定不明确时，借款人应如何支付利息",
        "rules": ["c674-1", "c674-2a", "c674-2b", "c674-2c"]
      },
      {
        "text": "借款利率的合法性，以及未约定利息、约定不明确时利息如何确定",
        "rules": ["c680-1", "c680-1b", "c680-2", "c680-3", "c680-3b"]
      }
    ],
    "conditions": [
      {
        "text": "存在贷款人向借款人提供借款、借款人到期返还借款并支付利息的合同",
        "rules": ["c667-1"]
      },
      {
        "text": "借款合同已成立，行为人为合同当事人",
        "rules": ["c668-1", "c667-oblig"]
      },
      {
        "text": "利息已预先在本金中扣除",
        "rules": ["c670-for", "c670-1"]
      },
      {
        "text": "对支付利息的期限有约定",
        "rules": ["c674-1"]
      },
      {
        "text": "对支付利息的期限没有约定或者约定不明确，且依据第510条的规定仍不能确定；借款期间不满一年，或者一年以上，或者一年以上且剩余期间不满一年",
        "rules": ["c674-2a", "c674-2b", "c674-2c"]
      },
      {
        "text": "借款合同对支付利息没有约定",
        "rules": ["c680-2"]
      },
      {
        "text": "借款合同对支付利息约定不明确，且当事人不能达成补充协议",
        "rules": ["c680-3", "c680-3b"]
      },
      {
        "text": "约定的利率违反国家有关规定（高利放贷）",
        "rules": ["c680-1", "c680-1b"]
      }
    ],
    "exceptions": [
      {
        "text": "自然人之间借款对合同形式另有约定的，可以不采用书面形式",
        "rules": ["c668-1"]
      },
      {
        "text": "自然人之间借款，对支付利息约定不明确且不能达成补充协议的，视为没有利息",
        "rules": ["c680-3b"]
      }
    ],
    "effects": [
      {
        "text": "借款人应当按照约定的期限返还借款并支付利息",
        "rules": ["c667-oblig"]
      },
      {
        "text": "借款合同应当采用书面形式（自然人之间另有约定的除外）",
        "rules": ["c668-1"]
      },
      {
        "text": "贷款人不得将利息预先在本金中扣除；已扣除的，借款人按照实际借款数额返还借款并计算利息",
        "rules": ["c670-for", "c670-1"]
      },
      {
        "text": "借款人按照约定的期限支付利息",
        "rules": ["c674-1"]
      },
      {
        "text": "利息支付期限不能确定的：借款期间不满一年的，在返还借款时一并支付；一年以上的，在每届满一年时支付；剩余期间不满一年的，在返还借款时一并支付",
        "rules": ["c674-2a", "c674-2b", "c674-2c"]
      },
      {
        "text": "禁止高利放贷，借款的利率不得违反国家有关规定；违反国家有关规定的利率约定无效",
        "rules": ["c680-1", "c680-1b"]
      },
      {
        "text": "借款合同对支付利息没有约定的，视为没有利息",
        "rules": ["c680-2"]
      },
      {
        "text": "对支付利息约定不明确且不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息",
        "rules": ["c680-3"]
      }
    ],
    "priority": [
      {
        "text": "自然人之间借款对利息约定不明确的，视为没有利息，该特别规则优先于按交易方式、交易习惯、市场利率确定利息的一般规则",
        "rules": ["c680-3b", "c680-3"]
      },
      {
        "text": "国家关于利率的强制性规定优先于合同约定，依交易方式、交易习惯、市场利率确定利息时亦不得违反",
        "rules": ["c680-1b", "c680-3"]
      }
    ],
    "distinguish": [
      {
        "text": "第668条第2款关于借款合同内容（借款种类、币种、用途、数额、利率、期限和还款方式等）的规定为示范性条款，不产生强制效力，不设规则",
        "rules": []
      },
      {
        "text": "第680条第2款“对支付利息没有约定”与第3款“对支付利息约定不明确”是两种不同情形，分别适用视为没有利息与依交易方式、交易习惯、市场利率确定利息的规则",
        "rules": ["c680-2", "c680-3"]
      },
      {
        "text": "笔记仅涉及借款人按期支付利息的义务与利率规则；第679条（自然人之间借款合同的成立）、第678条（借款展期）不在本条范围内",
        "rules": []
      }
    ]
  },
